      <div className="flex min-h-0 flex-1 flex-col rounded-3xl border border-border/70 bg-muted/15 p-3 sm:p-4">
        <div className="mb-2.5 grid gap-2 sm:grid-cols-[1fr_auto] sm:items-center">
